azureLogAnalytics.query:
let rates = PRICING_CL | summarize arg_max(TimeGenerated, *) by Model | project Model, InPer1K=InputTokensPrice, OutPer1K=OutputTokensPrice;
let gw = ApiManagementGatewayLogs | where $__timeFilter(TimeGenerated) | where Url has "/anthropic" | extend TeamId=tostring(coalesce(BackendRequestHeaders["x-caller-team-id"], ResponseHeaders["x-caller-team-id"])), TeamState=tostring(coalesce(BackendRequestHeaders["x-team-governance-state"], ResponseHeaders["x-team-governance-state"]));
let llm = ApiManagementGatewayLlmLog | where $__timeFilter(TimeGenerated) and isnotempty(RequestId) | extend Model=iff(isempty(ModelName), "unknown", replace_regex(ModelName, @"-\d{8}$", ""));
gw | join kind=inner llm on CorrelationId | where isnotempty(TeamId) and TeamState == "ok" | lookup kind=leftouter rates on Model | extend CostUsd=(PromptTokens * coalesce(InPer1K, 0.0) + CompletionTokens * coalesce(OutPer1K, 0.0)) / 1000.0 | summarize Requests=count(), Tokens=sum(TotalTokens), EstimatedCostUsd=round(sum(CostUsd), 4) by TeamId | order by EstimatedCostUsd desc

